//! 🫴️ Original CSV receiving frames own authored rows, paid indexes and partial logical records.
use super::{CsvSnapshot,CsvRecord,CsvField};
use semio_framework_os_kernel::sqlite_snapshot::{SqliteDatabase,SqliteTable,SqliteRow,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase};
use semio_framework_value::{ValueError,ValueRefusalKind};
#[cfg(test)]
use semio_framework_value::{NativeDecodeControl,NativeEncodeControl,RetainedCloneGrant,RetainedCloneProgress};
use store::NativeSnapshotBodyWallet;
use std::mem::size_of;
type Result<T>=std::result::Result<T,ValueError>;
pub(super) fn validate_subset(dialect:&semio_framework_artifact_reference::ArtifactDialect,control:&mut SqliteSnapshotControl<'_>,checkpoint:impl FnOnce()->Result<()>)->store::io_schema::IoResult<()>{
 checkpoint().map_err(store::io_schema::IoError::from_value_error)?;
 control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0).map_err(store::io_schema::IoError::from_value_error)?;
 if dialect.subset=="*"{return Ok(store::io_schema::IoOutcome::clean(()))}
 Err(store::io_schema::IoError::from_value_error(error(ValueRefusalKind::UnsupportedOwner,"CSV subset has no authored semantic validator")))
}
const SQL:&str=include_str!("../🗄️.sql");
const NAMES:[&str;3]=["csv_document","csv_record","csv_field"];
fn error(kind:ValueRefusalKind,message:&'static str)->ValueError{ValueError::literal(kind,message)}
fn invalid(message:&'static str)->ValueError{error(ValueRefusalKind::InvalidValue,message)}
fn ordinal(value:usize)->Result<i64>{i64::try_from(value).map_err(|_|error(ValueRefusalKind::WorkLimit,"CSV ordinal exceeds signed SQL extent"))}
fn definition(index:usize)->&'static str{SQL.split(';').filter(|word|!word.trim().is_empty()).nth(index).unwrap().trim()}
fn empty_snapshot()->CsvSnapshot{CsvSnapshot{schema:String::new(),has_header:false,records:Vec::new()}}
use semio_framework_os_kernel::sqlite_snapshot::artifact::receiving::{Direction,Projection,Scalar,cell,text_cell,row,push_row,sort,identity_position as record_position,settle};
type Port<'a,'b,'c>=semio_framework_os_kernel::sqlite_snapshot::artifact::receiving::Port<'a,'b,'c,NativeSnapshotBodyWallet>;
fn fields(rows:&[SqliteRow],indices:&[usize],identity:i64,port:&mut Port<'_,'_,'_>)->Result<std::ops::Range<usize>>{semio_framework_os_kernel::sqlite_snapshot::artifact::receiving::parent_range(rows,indices,identity,1,port)}
fn project(source:&CsvSnapshot,frame:&mut Projection,port:&mut Port<'_,'_,'_>)->Result<()>{
 let limits=port.control.limits();let schema_bytes=(0..3).map(|index|NAMES[index].len()+definition(index).len()).sum::<usize>();if schema_bytes>limits.max_schema_bytes||limits.max_tables<3||limits.max_columns<5{return Err(error(ValueRefusalKind::OwnershipLimit,"CSV authored schema exceeds original ceiling"))}
 let mut fields=0usize;for record in &source.records{port.work(2,0)?;fields=fields.checked_add(record.fields.len()).ok_or_else(||error(ValueRefusalKind::WorkLimit,"CSV field count overflow"))?;port.control.check_rows(1usize.checked_add(source.records.len()).and_then(|count|count.checked_add(fields)).ok_or_else(||error(ValueRefusalKind::WorkLimit,"CSV row count overflow"))?)?;}let total=1+source.records.len()+fields;port.control.check_rows(total)?;
 port.vector(3,&mut frame.database.tables,1)?;for(index,count)in[1,source.records.len(),fields].into_iter().enumerate(){port.work(2,size_of::<SqliteTable>())?;frame.database.tables.push(SqliteTable{name:String::new(),sql:String::new(),rows:Vec::new()});let table=&mut frame.database.tables[index];port.text(NAMES[index],&mut table.name,2)?;port.text(definition(index),&mut table.sql,2)?;port.vector(count,&mut table.rows,2)?;}
 row(frame,1,3,port)?;text_cell(frame,&source.schema,port)?;cell(frame,Scalar::Integer(i64::from(source.has_header)),port)?;push_row(frame,0,port)?;
 let mut field_id=0usize;for(index,record)in source.records.iter().enumerate(){let record_id=ordinal(index+1)?;row(frame,record_id,3,port)?;cell(frame,Scalar::Integer(1),port)?;cell(frame,Scalar::Integer(ordinal(index)?),port)?;push_row(frame,1,port)?;for(index,field)in record.fields.iter().enumerate(){field_id=field_id.checked_add(1).ok_or_else(||error(ValueRefusalKind::WorkLimit,"CSV field identity overflow"))?;row(frame,ordinal(field_id)?,5,port)?;cell(frame,Scalar::Integer(record_id),port)?;cell(frame,Scalar::Integer(ordinal(index)?),port)?;text_cell(frame,&field.value,port)?;cell(frame,Scalar::Integer(i64::from(field.quoted)),port)?;push_row(frame,2,port)?;}}
 port.control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,total,total)
}
#[derive(semio_framework_value::RetireOwned)]
struct Reconstruction{snapshot:CsvSnapshot,records:Vec<usize>,record_ids:Vec<usize>,fields:Vec<usize>,field_ids:Vec<usize>,used_fields:usize}
impl Reconstruction{fn new()->Self{Self{snapshot:empty_snapshot(),records:Vec::new(),record_ids:Vec::new(),fields:Vec::new(),field_ids:Vec::new(),used_fields:0}}}
fn table<'a>(database:&'a SqliteDatabase,name:&str)->Result<&'a SqliteTable>{database.tables.iter().find(|table|table.name.eq_ignore_ascii_case(name)).ok_or_else(||invalid("CSV authored table is missing"))}
fn integer(row:&SqliteRow,column:usize)->Result<i64>{match row.values.get(column){Some(SqliteValue::Integer(value))=>Ok(*value),_=>Err(invalid("CSV integer cell is invalid"))}}
fn text(row:&SqliteRow,column:usize)->Result<&str>{match row.values.get(column){Some(SqliteValue::Text(value))=>Ok(value),_=>Err(invalid("CSV text cell is invalid"))}}
fn flag(row:&SqliteRow,column:usize)->Result<bool>{match integer(row,column)?{0=>Ok(false),1=>Ok(true),_=>Err(invalid("CSV authored flag requires zero or one"))}}
fn schema(database:&SqliteDatabase,port:&mut Port<'_,'_,'_>)->Result<()>{let authored=[0,1,2].map(|index|semio_framework_os_kernel::sqlite_snapshot::artifact::receiving::AuthoredTable{name:NAMES[index],declaration:definition(index),columns:[3,3,5][index]});semio_framework_os_kernel::sqlite_snapshot::artifact::receiving::validate_schema(database,&authored,port)}
fn reconstruct(database:&SqliteDatabase,frame:&mut Reconstruction,port:&mut Port<'_,'_,'_>)->Result<()>{
 schema(database,port)?;port.control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;let documents=&table(database,NAMES[0])?.rows;if documents.len()!=1||documents[0].rowid!=1||documents[0].values.len()!=3||integer(&documents[0],0)?!=1{return Err(invalid("CSV requires one authored document identity"))}let document=&documents[0];port.control.admit_reconstruction_bytes(8)?;port.work(1,size_of::<bool>())?;frame.snapshot.has_header=flag(document,2)?;
 let records=&table(database,NAMES[1])?.rows;let children=&table(database,NAMES[2])?.rows;port.vector(records.len(),&mut frame.records,1)?;port.vector(records.len(),&mut frame.record_ids,1)?;port.vector(children.len(),&mut frame.fields,1)?;port.vector(children.len(),&mut frame.field_ids,1)?;
 for(index,row)in records.iter().enumerate(){port.work(1,0)?;if row.values.len()!=3||row.rowid<=0||integer(row,0)?!=row.rowid||integer(row,1)?!=1{return Err(invalid("CSV record identity or document ownership is invalid"))}port.work(1,2*size_of::<usize>())?;frame.records.push(index);frame.record_ids.push(index);}
 sort(&mut frame.records,port,|a,b|Ok(integer(&records[a],2)?.cmp(&integer(&records[b],2)?)))?;sort(&mut frame.record_ids,port,|a,b|Ok(records[a].rowid.cmp(&records[b].rowid)))?;for pair in frame.record_ids.windows(2){port.work(1,0)?;if records[pair[0]].rowid==records[pair[1]].rowid{return Err(invalid("CSV record identity is duplicated"))}}
 for(index,row)in children.iter().enumerate(){port.work(1,0)?;if row.values.len()!=5||row.rowid<=0||integer(row,0)?!=row.rowid{return Err(invalid("CSV field identity or width is invalid"))}if record_position(records,&frame.record_ids,integer(row,1)?,port)?.is_none(){return Err(invalid("CSV field has an unknown record"))}port.work(1,2*size_of::<usize>())?;frame.fields.push(index);frame.field_ids.push(index);}
 sort(&mut frame.fields,port,|a,b|Ok(integer(&children[a],1)?.cmp(&integer(&children[b],1)?).then(integer(&children[a],2)?.cmp(&integer(&children[b],2)?))))?;sort(&mut frame.field_ids,port,|a,b|Ok(children[a].rowid.cmp(&children[b].rowid)))?;for pair in frame.field_ids.windows(2){port.work(1,0)?;if children[pair[0]].rowid==children[pair[1]].rowid{return Err(invalid("CSV field identity is duplicated"))}}
 let schema=text(document,1)?;port.control.admit_reconstruction_bytes(schema.len())?;port.text(schema,&mut frame.snapshot.schema,1)?;port.vector(records.len(),&mut frame.snapshot.records,2)?;
 for(position,index)in frame.records.iter().copied().enumerate(){let record=&records[index];if integer(record,2)?!=ordinal(position)?{return Err(invalid("CSV record ordinals must be contiguous and unique"))}let members=fields(children,&frame.fields,record.rowid,port)?;port.work(2,size_of::<CsvRecord>())?;frame.snapshot.records.push(CsvRecord{fields:Vec::new()});let output=frame.snapshot.records.last_mut().unwrap();port.vector(members.len(),&mut output.fields,3)?;
  for(position,index)in members.enumerate(){let row=&children[frame.fields[index]];port.work(3,0)?;if integer(row,2)?!=ordinal(position)?{return Err(invalid("CSV field ordinals must be contiguous and unique"))}port.control.admit_reconstruction_bytes(8)?;let quoted=flag(row,4)?;port.work(3,size_of::<CsvField>())?;output.fields.push(CsvField{value:String::new(),quoted});let value=text(row,3)?;port.control.admit_reconstruction_bytes(value.len())?;port.text(value,&mut output.fields.last_mut().unwrap().value,4)?;port.work(3,size_of::<usize>())?;frame.used_fields+=1;}
 }
 if frame.used_fields!=children.len(){return Err(invalid("CSV field consumption is incomplete"))}let total=1+records.len()+children.len();port.control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,total,total)
}
pub(super)fn project_receiving(source:&CsvSnapshot,control:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotDecodeOwner<'_,'_>)->Result<SqliteDatabase>{let result=(||{let remaining=control.allocation_remaining_bytes();if remaining==0{return Err(error(ValueRefusalKind::OwnershipLimit,"CSV projection has no original backing allowance"))}let before=owner.native().owned_bytes();let maximum=before.checked_add(remaining).ok_or_else(||error(ValueRefusalKind::OwnershipLimit,"CSV original allocation ceiling overflow"))?;let result=owner.scoped_native(maximum,&mut |_|true,|owner|owner.receive::<Projection,SqliteDatabase>(|slot,native,body|{let mut port=Port{control,native:Direction::Decode(native),body};port.work(1,size_of::<Projection>())?;*slot=Some(Projection::new());let frame=slot.as_mut().unwrap();project(source,frame,&mut port)?;port.work(1,size_of::<SqliteDatabase>())?;Ok(std::mem::replace(&mut frame.database,SqliteDatabase{tables:Vec::new()}))}));settle(control,remaining,before,owner.native().owned_bytes())?;result})();result.map_err(|error|error.with_retained_progress(owner.progress()))}
pub(super)fn reconstruct_receiving(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotEncodeOwner<'_,'_>)->Result<CsvSnapshot>{let result=(||{let remaining=control.allocation_remaining_bytes();if remaining==0{return Err(error(ValueRefusalKind::OwnershipLimit,"CSV reconstruction has no original backing allowance"))}let before=owner.native().owned_bytes();let maximum=before.checked_add(remaining).ok_or_else(||error(ValueRefusalKind::OwnershipLimit,"CSV original allocation ceiling overflow"))?;let result=owner.scoped_native(maximum,&mut |_|true,|owner|owner.receive::<Reconstruction,CsvSnapshot>(|slot,native,body|{let mut port=Port{control,native:Direction::Encode(native),body};port.work(1,size_of::<Reconstruction>())?;*slot=Some(Reconstruction::new());let frame=slot.as_mut().unwrap();reconstruct(database,frame,&mut port)?;port.work(1,size_of::<CsvSnapshot>())?;Ok(std::mem::replace(&mut frame.snapshot,empty_snapshot()))}));settle(control,remaining,before,owner.native().owned_bytes())?;result})();result.map_err(|error|error.with_retained_progress(owner.progress()))}
